window.SCHOOL_LISTENING={"../assets/media/ad3dd7f86df49ff1ac68b0751d2f3c7a5866640f7387f4ca78784dd2330e3481.mp3":[{"id":"PPT_ad3dd7f86df49ff1","audioId":"PPT_ad3dd7f86df49ff1","title":"Book 2 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 93","duration":20.24,"cues":[{"start":0,"end":2,"text":"three .four","coverage":1},{"start":3.42,"end":4.38,"text":"one","coverage":1},{"start":5.58,"end":10.36,"text":"You will hear the main ideas and some additional information","coverage":1},{"start":12.2,"end":13.16,"text":"two","coverage":1},{"start":13.84,"end":18.32,"text":"You will hear the main ideas as well as some additional information","coverage":1}],"file":"073e0c29f3919ddd9143.js","track":0,"media":"../assets/media/ad3dd7f86df49ff1ac68b0751d2f3c7a5866640f7387f4ca78784dd2330e3481.mp3"}],"../assets/media/22b30a333f4ad3dce3ba0e0e52373515665dc9c6342cb42be553251afd25ab58.mp3":[{"id":"PPT_22b30a333f4ad3dc","audioId":"PPT_22b30a333f4ad3dc","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 57","duration":25.81,"cues":[{"start":0,"end":2,"text":"three .two","coverage":1},{"start":3.64,"end":7.06,"text":"one Can you wash the pan on the cooker?","coverage":1},{"start":9.04,"end":9.68,"text":"two","coverage":1},{"start":10.5,"end":12.56,"text":"Please don't sit on the sheet","coverage":1},{"start":14.46,"end":15.1,"text":"three","coverage":1},{"start":15.98,"end":18.34,"text":"Please sew me a blue dress","coverage":1},{"start":20.16,"end":20.8,"text":"four","coverage":1},{"start":21.4,"end":23.88,"text":"This cheap wool is not nice","coverage":1}],"file":"5b74096232f315fef20d.js","track":0,"media":"../assets/media/22b30a333f4ad3dce3ba0e0e52373515665dc9c6342cb42be553251afd25ab58.mp3"}],"../assets/media/9792dd26e61230623d241635ddff44e87e1022f5c759eb414afc3b86cf662d61.mp3":[{"id":"PPT_9792dd26e6123062","audioId":"PPT_9792dd26e6123062","title":"Book 2 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 99","duration":148.43,"cues":[{"start":0,"end":1.84,"text":"three .five","coverage":1},{"start":3.02,"end":11.64,"text":"For a long time people have asked the same question Do computers stop us from learning and developing?","coverage":1},{"start":12.26,"end":13.84,"text":"Do they make us stupid?","coverage":1},{"start":14.64,"end":20.76,"text":"A recent study at Columbia University in New York looked at this question in","coverage":1},{"start":21.22,"end":30.64,"text":"particular how computers affect our memory They wanted to find out if computers have changed the way we remember information","coverage":1},{"start":32.1,"end":52.8,"text":"First the scientists did research on what happens when people are asked difficult questions They found that what we think when we hear difficult questions has changed because of websites like Google When people were asked difficult questions in the past","coverage":1},{"start":53.36,"end":69.02,"text":"Scientists believe they tried to think of the answer to the question However because of modern technology the first thing people think about now is how to find the answer They don't try to answer it themselves","coverage":1},{"start":69.58,"end":77.88,"text":"For example, they think about what they might put into Google, but in the past they thought about the question itself","coverage":1},{"start":79.16,"end":109.58,"text":"second Scientists found that computers have changed the type of information we remember there are advantages and disadvantages to these changes a Disadvantage is that it seems that people now forget facts Especially if they know the information will be saved in a file on the other hand an advantage Is that they remember the location of the fact in other words where to find it in?","coverage":1},{"start":109.58,"end":110.36,"text":"one test","coverage":1},{"start":110.94,"end":126.4,"text":"scientists told university students some facts and Also where the facts were saved in a file Most of the students couldn't remember the facts, but they were able to remember the files and the location of the facts","coverage":1},{"start":126.94,"end":134.76,"text":"In conclusion it seems that computers are not making us stupid, but they are making us lazy","coverage":1},{"start":135.76,"end":146.5,"text":"Scientists believe that we are spending time remembering where and how we can find things But we're not trying to remember the information itself anymore","coverage":1}],"file":"81bc7f645da58faab153.js","track":0,"media":"../assets/media/9792dd26e61230623d241635ddff44e87e1022f5c759eb414afc3b86cf662d61.mp3"}],"../assets/media/ee4ee5dd52201715c930952f06342618453680e08e0ef1b1bea0607817429887.mp3":[{"id":"PPT_ee4ee5dd52201715","audioId":"PPT_ee4ee5dd52201715","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 51","duration":40.28,"cues":[{"start":0,"end":1.72,"text":"Unit three,","coverage":1},{"start":2.46,"end":3.44,"text":"three .one","coverage":1},{"start":5.2,"end":6,"text":"one","coverage":1},{"start":6.6,"end":7.74,"text":"sort","coverage":1},{"start":9.64,"end":10.48,"text":"two","coverage":1},{"start":11.16,"end":12.12,"text":"cheap","coverage":1},{"start":13.52,"end":14.92,"text":"three","coverage":1},{"start":15.6,"end":16.56,"text":"wash","coverage":1},{"start":18.24,"end":19.3,"text":"four","coverage":1},{"start":19.88,"end":20.74,"text":"see","coverage":1},{"start":22.32,"end":23.72,"text":"five","coverage":1},{"start":24.48,"end":25.34,"text":"sheet","coverage":1},{"start":26.74,"end":28.14,"text":"six","coverage":1},{"start":28.96,"end":29.68,"text":"chair","coverage":1},{"start":31.18,"end":32,"text":"seven","coverage":1},{"start":32.58,"end":34.2,"text":"catch","coverage":1},{"start":36,"end":36.78,"text":"eight","coverage":1},{"start":37.6,"end":38.3,"text":"shoes","coverage":1}],"file":"84c27e162a613701dc46.js","track":0,"media":"../assets/media/ee4ee5dd52201715c930952f06342618453680e08e0ef1b1bea0607817429887.mp3"}],"../assets/media/4409f13af249a81880eea49c63923251ebd25834f7e573c656a669dcbce3a082.mp3":[{"id":"PPT_4409f13af249a818","audioId":"PPT_4409f13af249a818","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 66","duration":280.32,"cues":[{"start":0,"end":2.3,"text":"three .three","coverage":1},{"start":3.4,"end":9.14,"text":"Welcome to University Podcasts, programs made by students for students.","coverage":1},{"start":9.84,"end":10.88,"text":"I'm Chen Hu,","coverage":1},{"start":11.32,"end":13.78,"text":"and this is Science with a Professor.","coverage":1},{"start":14.6,"end":20.64,"text":"Our subject is technology development, and our guest is Professor Joanne Kent,","coverage":1},{"start":21.26,"end":22.34,"text":"expert in robotics.","coverage":1},{"start":23.14,"end":24.28,"text":"Thanks for coming, Professor.","coverage":1},{"start":25.28,"end":27.18,"text":"When we think of robots,","coverage":1},{"start":27.72,"end":33.86,"text":"we generally think of simple robots that clean the floor in our home or build a car in a factory.","coverage":1},{"start":34.62,"end":38.48,"text":"But how close are we to having robots that are like people?","coverage":1},{"start":39.38,"end":43.62,"text":"Well, we already have some robots that look like people,","coverage":1},{"start":44.08,"end":47.36,"text":"and technology is developing more every day.","coverage":1},{"start":48,"end":54.16,"text":"Robots weren't used very much in the past, since they were always really expensive.","coverage":1},{"start":54.64,"end":60.58,"text":"But because they're cheaper now, they're being used in new and interesting ways.","coverage":1},{"start":61.78,"end":62.76,"text":"What kinds of ways?","coverage":1},{"start":63.94,"end":65.48,"text":"Well, as you said,","coverage":1},{"start":66.1,"end":69.22,"text":"robots have been used in factories for years.","coverage":1},{"start":69.78,"end":75.8,"text":"Singapore and Korea are among the top five countries in the world with factory robots,","coverage":1},{"start":76.32,"end":80.66,"text":"and Japan has robots that serve food in some cafes.","coverage":1},{"start":81.42,"end":83.24,"text":"But now in the US,","coverage":1},{"start":83.62,"end":88.74,"text":"some restaurants are testing robots which work in the kitchen and cook food,","coverage":1},{"start":89.06,"end":91.66,"text":"or which deliver pizza to homes.","coverage":1},{"start":92.48,"end":92.88,"text":"Also,","coverage":1},{"start":93.28,"end":97.82,"text":"robots are being developed to work on farms and help grow food.","coverage":1},{"start":98.4,"end":102.24,"text":"They can pick fruit, for example, or look at plant health.","coverage":1},{"start":103.28,"end":104.04,"text":"Interesting.","coverage":1},{"start":104.66,"end":108.48,"text":"But what about robots that look after or help people?","coverage":1},{"start":109.06,"end":110.22,"text":"Do we have those?","coverage":1},{"start":111.1,"end":122.44,"text":"Well, many companies are developing robots to help people who have a disability or people who can't always do housework or care for themselves easily.","coverage":1},{"start":123.18,"end":130.64,"text":"They might need help from robots that can carry things around the house or deliver medicine on time.","coverage":1},{"start":131.36,"end":135.08,"text":"These types of robots are becoming less expensive.","coverage":1},{"start":135.58,"end":139.92,"text":"Having a robot means people are able to stay in their own homes.","coverage":1},{"start":141.06,"end":145.94,"text":"So do people have a much better quality of life thanks to these new types of robots?","coverage":1},{"start":147.2,"end":155.68,"text":"Yes, but at this time, it's too expensive to have robots at home that can pick people up or feed them.","coverage":1},{"start":155.68,"end":159.48,"text":"Also, when robots were used in care homes,","coverage":1},{"start":159.92,"end":163.54,"text":"the nurses found that the robots didn't save time.","coverage":1},{"start":164.48,"end":165.32,"text":"Why is that?","coverage":1},{"start":166.08,"end":169.06,"text":"The robots had to be moved and watched.","coverage":1},{"start":169.46,"end":176.1,"text":"The nurses spent time looking after the robots, and so they had less time to look after the people.","coverage":1},{"start":176.58,"end":179.86,"text":"They stopped using the robots due to the lost time.","coverage":1},{"start":181,"end":181.74,"text":"I see.","coverage":1},{"start":182.58,"end":185.5,"text":"What are some other ways that robots are used?","coverage":1},{"start":186.62,"end":192.38,"text":"These days, people use robots for science research, to repair equipment in the ocean,","coverage":1},{"start":192.8,"end":195.86,"text":"and as assistance to doctors and librarians.","coverage":1},{"start":197.22,"end":197.6,"text":"Really?","coverage":1},{"start":198.12,"end":199.66,"text":"What kind of science research?","coverage":1},{"start":200.56,"end":202.8,"text":"I know about robots on the planet Mars.","coverage":1},{"start":203.9,"end":210.04,"text":"Yes, robots go to places that we can't go to collect information, like on Mars.","coverage":1},{"start":210.4,"end":217.68,"text":"They can prevent accidents by doing dangerous things, and they can go into areas with bad pollution.","coverage":1},{"start":218.76,"end":222.3,"text":"And you also said robots could be doctors or librarians.","coverage":1},{"start":222.88,"end":230.26,"text":"Does that mean I shouldn't study for a degree in library studies because a robot is going to take all the librarian's jobs?","coverage":1},{"start":231.7,"end":232.38,"text":"No,","coverage":1},{"start":232.86,"end":236.78,"text":"robots only help with the boring parts of being a librarian.","coverage":1},{"start":237.21,"end":243.48,"text":"They use barcodes to look for books on the shelves or put books in the right place.","coverage":1},{"start":245.88,"end":247.7,"text":"But what about a robot doctor?","coverage":1},{"start":248.58,"end":251.52,"text":"Am I going to see a robot when I go to the doctors?","coverage":1},{"start":252.82,"end":259.24,"text":"No, not yet, but doctors can use robotic arms to help them do surgery.","coverage":1},{"start":260.26,"end":264.8,"text":"People stay in hospital for a shorter time because of fewer problems.","coverage":1},{"start":265.62,"end":266.14,"text":"Well,","coverage":1},{"start":266.8,"end":269.88,"text":"we've heard about robots that clean your house, cook food,","coverage":1},{"start":270.22,"end":270.9,"text":"do research,","coverage":1},{"start":271.3,"end":272.92,"text":"and even help your doctor too.","coverage":1},{"start":273.68,"end":274,"text":"Okay,","coverage":1},{"start":274.4,"end":276.98,"text":"we have some questions coming in, so let's hear the first one.","coverage":1}],"file":"92513126d5ed9a3e984b.js","track":0,"media":"../assets/media/4409f13af249a81880eea49c63923251ebd25834f7e573c656a669dcbce3a082.mp3"}],"../assets/media/209560db93648036e8e5392a33a2ef5986d9a5e23deef31f35f3779085d29541.mp3":[{"id":"PPT_209560db93648036","audioId":"PPT_209560db93648036","title":"Book 2 · Unit 3 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 177","duration":64.47,"cues":[{"start":0,"end":2.3,"text":"three .six","coverage":1},{"start":4.32,"end":5,"text":"one.","coverage":1},{"start":5.4,"end":8.5,"text":"When people were asked difficult questions in the past,","coverage":1},{"start":9.3,"end":12.68,"text":"scientists believe they tried to think of the answer to the question.","coverage":1},{"start":13.4,"end":13.8,"text":"However,","coverage":1},{"start":14.3,"end":15.92,"text":"because of modern technology,","coverage":1},{"start":16.56,"end":20.32,"text":"the first thing people think about now is how to find the answer.","coverage":1},{"start":22.3,"end":22.98,"text":"two.","coverage":1},{"start":23.84,"end":24.68,"text":"For example,","coverage":1},{"start":25.12,"end":31.46,"text":"they think about what they might put into Google, but in the past they thought about the question itself.","coverage":1},{"start":33.92,"end":34.46,"text":"three.","coverage":1},{"start":35.54,"end":37.96,"text":"It seems that people now forget facts,","coverage":1},{"start":38.52,"end":42.32,"text":"especially if they know the information will be saved in a file.","coverage":1},{"start":42.76,"end":44.28,"text":"On the other hand,","coverage":1},{"start":44.76,"end":48.06,"text":"an advantage is they remember the location of the fact.","coverage":1},{"start":48.58,"end":49.6,"text":"In other words,","coverage":1},{"start":50.04,"end":51.72,"text":"where to find it.","coverage":1},{"start":53.18,"end":53.86,"text":"four.","coverage":1},{"start":54.88,"end":59.46,"text":"In conclusion, it seems that computers are not making us stupid,","coverage":1},{"start":60.24,"end":62.5,"text":"but they are making us lazy.","coverage":1}],"file":"c2ca4aab6e21b5cb6deb.js","track":0,"media":"../assets/media/209560db93648036e8e5392a33a2ef5986d9a5e23deef31f35f3779085d29541.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 Do you have any things in your home that can connect to the internet? What are they? If not, why not?Possible answer: Our television connects to the internet so that we can watch programmes.","slide":4,"shape":"14","bookPage":"60"},{"text":"2 What things do you own that do not work without the internet?Possible answer: Our smart speaker needs the internet to find online information.","slide":4,"shape":"16","bookPage":"60"},{"text":"1 What do you think you can learn from this video?Possible answer: It might explain how connected homes, fridges, cars and cities work.","slide":6,"shape":"24","bookPage":"60"},{"text":"2 How do you think the technology in the photos can help people?Possible answer: It could save energy, help people buy food and make travelling safer.","slide":6,"shape":"25","bookPage":"60"},{"text":"1 Smart buildings help save energy.","slide":15,"shape":"18","bookPage":"60"},{"text":"2 A smart fridge can help you not waste food.","slide":15,"shape":"19","bookPage":"60"},{"text":"3 Smart car technology makes roads safer.","slide":15,"shape":"20","bookPage":"60"},{"text":"a You know how old something is, so you can reduce waste.Answer: 3","slide":17,"shape":"11","bookPage":"61"},{"text":"b The lights have sensors which collect information about … the amount of light used.Answer: 2","slide":17,"shape":"13","bookPage":"61"},{"text":"c If there is a problem, the car lets the driver know …Answer: 4","slide":18,"shape":"11","bookPage":"61"},{"text":"d If it’s going to get cold, the heating can turn on by itself.Answer: 1","slide":18,"shape":"13","bookPage":"61"},{"text":"e Whole cities can use this smart technology.Answer: 5","slide":19,"shape":"12","bookPage":"61"},{"text":"1 What information do light sensors collect?Answer: They collect information about movement, power use and the amount of lightused.","slide":22,"shape":"17","bookPage":"61"},{"text":"2 What does a smart car tell a driver to do if there is a problem?Answer: It tells the driver to take the car to a mechanic.","slide":22,"shape":"19","bookPage":"61"},{"text":"3 What is the name of the traffic control technology in Singapore?Answer: The Intelligent Transport System.","slide":23,"shape":"11","bookPage":"61"},{"text":"4 What information do the sensors under the road collect?Answer: They sense the number of vehicles and where they are.","slide":23,"shape":"13","bookPage":"61"},{"text":"Other uses not in the videoA connected watch can share exercise records. A connected doorbell can showwho is at the door. A sensor can warn us about a water leak.","slide":25,"shape":"12","bookPage":"61"},{"text":"1 Is there any smart technology that you do not use? Why / Why not?Possible answer: I do not use a smart fridge because an ordinary fridge is enough for me.","slide":27,"shape":"17","bookPage":"61"},{"text":"2 What are some disadvantages of the internet of things?Possible answer: Connected devices may cost more, and some functions may stop when theinternet is unavailable.","slide":27,"shape":"19","bookPage":"61"},{"text":"3 What new things did you learn from the video?Possible answer: I learned that road sensors can help change traffic-light timing.","slide":28,"shape":"18","bookPage":"61"},{"text":"accident — an unexpected event that causes injury or damage","slide":42,"shape":"17","bookPage":"62"},{"text":"disability — a condition that makes some activities difficult","slide":42,"shape":"18","bookPage":"62"},{"text":"look after — take care of somebody or something","slide":42,"shape":"19","bookPage":"62"},{"text":"assistant — a person or thing that helps someone","slide":42,"shape":"20","bookPage":"62"},{"text":"deliver — take something to a person or place","slide":42,"shape":"6","bookPage":"62"},{"text":"research — study to discover information","slide":42,"shape":"7","bookPage":"62"},{"text":"collect — bring things or information together","slide":42,"shape":"8","bookPage":"62"},{"text":"information — facts or details about something","slide":43,"shape":"18","bookPage":"62"},{"text":"develop — make or improve something over time","slide":43,"shape":"19","bookPage":"62"},{"text":"What do you know about robots?\nWhat do you want to know?\nHow will you find out?\nMost robots don’t look like people.\nHow much does a robot cost?\nI can look on the internet.\nSome robots clean floors.\nCan a home robot cook a whole meal?\nRead information from the maker and compare what different robots can do.","slide":46,"shape":"13","bookPage":"62"},{"text":"1 What do you think each robot does? I think the robot in photo a cooks.Possible answer: a cooks; b cleans floors; c works underwater; d helps someone in a workplace.","slide":49,"shape":"17","bookPage":"63"},{"text":"2 Who do you think uses these robots? Why?Possible answer: A restaurant, a person at home, a researcher and a factory worker could use them.","slide":49,"shape":"19","bookPage":"63"},{"text":"3 Do you want robots like these? Why / Why not?Possible answer: I would like a cleaning robot because it would save time.","slide":50,"shape":"18","bookPage":"63"},{"text":"1 short / sort","slide":52,"shape":"15","bookPage":"63"},{"text":"2 sheep / cheap","slide":52,"shape":"16","bookPage":"63"},{"text":"3 wash / watch","slide":52,"shape":"17","bookPage":"63"},{"text":"4 sea / she","slide":52,"shape":"18","bookPage":"63"},{"text":"5 seat / sheet","slide":52,"shape":"19","bookPage":"63"},{"text":"6 chair / share","slide":52,"shape":"7","bookPage":"63"},{"text":"7 cash / catch","slide":52,"shape":"8","bookPage":"63"},{"text":"8 shoes / choose","slide":53,"shape":"16","bookPage":"63"},{"text":"Partner A → Partner Bshort → sort; sheep → cheap; wash → watch; sea → she","slide":56,"shape":"14","bookPage":"63"},{"text":"Partner A → Partner Bseat → sheet; chair → share; cash → catch; shoes → choose","slide":56,"shape":"16","bookPage":"63"},{"text":"1 Can you wash the pan on the cooker?","slide":58,"shape":"15","bookPage":"64"},{"text":"2 Please don’t sit on the sheet.","slide":58,"shape":"17","bookPage":"64"},{"text":"3 Please sew me a blue dress.","slide":58,"shape":"19","bookPage":"64"},{"text":"4 This cheap wool is not nice.","slide":58,"shape":"8","bookPage":"64"},{"text":"1 What kinds of robots are there?Possible answer: There are cleaning, factory and underwater robots.","slide":60,"shape":"17","bookPage":"64"},{"text":"2 Do you think robots are cheap or expensive?Possible answer: Their prices vary with their jobs and design.","slide":60,"shape":"18","bookPage":"64"},{"text":"3 How do you think robots can look after people with disabilities?Possible answer: Robots could carry things or deliver medicine.","slide":60,"shape":"19","bookPage":"64"},{"text":"4 Can robots work in the seas and oceans? Why / Why not?Possible answer: Yes. Some robots can work underwater.","slide":60,"shape":"20","bookPage":"64"},{"text":"5 Can robots help scientists, doctors or librarians?Possible answer: Yes. Robots can collect information, help doctors and find books.","slide":61,"shape":"18","bookPage":"64"},{"text":"Simple robots: (1) clean floors, build cars","slide":68,"shape":"7","bookPage":"64"},{"text":"Today: Robots are (2) cheaper, used in new and interesting ways","slide":68,"shape":"9","bookPage":"64"},{"text":"Used in (3) factories in Singapore and Korea, cafés in Japan","slide":68,"shape":"10","bookPage":"64"},{"text":"Food robotsUS: cook, (4) deliver pizzas, work on farms to (5) grow food","slide":68,"shape":"11","bookPage":"64"},{"text":"Caring robotsAdvantages: help people with disabilities or unable to do (6) housework: carry things,bring medicine. Now less expensive; people can stay (7) in their own homes, better life","slide":69,"shape":"7","bookPage":"64"},{"text":"Disadvantages: in care homes, (8) nurses needed to watch robots","slide":69,"shape":"8","bookPage":"64"},{"text":"Assistant robotsHelp scientists to collect (9) information, go to dangerous or polluted places","slide":69,"shape":"9","bookPage":"64"},{"text":"Robotic (10) arms help doctors do surgery; people get well faster","slide":69,"shape":"11","bookPage":"64"},{"text":"Compare with the podcastCheck each gap against the complete answers. Then identify which of yourpredictions were supported, changed or not discussed.","slide":72,"shape":"12","bookPage":"65"},{"text":"1 Cost in the pastRobots weren’t used very much in the past since they were always reallyexpensive.","slide":74,"shape":"18","bookPage":"65"},{"text":"2 Quality of lifePeople have a much better quality of life thanks to these new types of robots.","slide":74,"shape":"20","bookPage":"65"},{"text":"3 Care homesThey stopped using the robots due to the lost time.","slide":74,"shape":"22","bookPage":"65"},{"text":"4 Hospital staysPeople stay in hospital a shorter time because of fewer problems.","slide":75,"shape":"13","bookPage":"65"},{"text":"Event\nReason\nRobots weren’t used very much in the past\nsince they were (1) always really expensive.\nPeople have a much better quality of life\nthanks to these (2) new types of robots.\nThey stopped using the robots\ndue to the lost (3) time.\nPeople stay in hospital a shorter time\nbecause of fewer (4) problems.","slide":76,"shape":"15","bookPage":"65"},{"text":"1. The podcast is made by university learners for students.","slide":79,"shape":"5","bookPage":null},{"text":"11. Why are robots used in more ways now?\nA. Their price has fallen, allowing more uses.\nB. Their appearance has improved, allowing more uses.\nC. Their speed has increased, allowing more uses.","slide":79,"shape":"8","bookPage":null},{"text":"1 When somebody asks you a question, what is the first thing you usually do – try to think of the answer yourself or use your phone to find the answer? Why?Possible answer: I try to think of an answer first, especially if the person wants my opinion.","slide":83,"shape":"17","bookPage":"69"},{"text":"2 When you need to find something out, do you use your phone or ask a friend? Why?Possible answer: I ask a friend about their experience, but use my phone to check a fact.","slide":83,"shape":"19","bookPage":"69"},{"text":"3 How could using a computer to help you find information change the way your brain works?Possible answer: We might remember where to find information instead of remembering theinformation itself.","slide":84,"shape":"18","bookPage":"69"},{"text":"a  affect (v) to cause somebody or something to change","slide":93,"shape":"6","bookPage":"70"},{"text":"b  stupid (adj) silly or not intelligent","slide":93,"shape":"7","bookPage":"70"},{"text":"c  file (n) a collection of information stored in one place on a computer","slide":93,"shape":"8","bookPage":"70"},{"text":"d  lazy (adj) not wanting to work or use any effort","slide":93,"shape":"9","bookPage":"70"},{"text":"e  memory (n) the ability to remember","slide":93,"shape":"10","bookPage":"70"},{"text":"1 You will hear the main ideas and some additional information.","slide":95,"shape":"16","bookPage":"70"},{"text":"2 You will hear the main ideas as well as some additional information.","slide":95,"shape":"17","bookPage":"70"},{"text":"1 Which letter do we often not pronounce when we say and?The letter d.","slide":98,"shape":"19","bookPage":"71"},{"text":"2 Is the letter a in and usually strong /æ/ or weak /ə/?Weak /ə/.","slide":98,"shape":"20","bookPage":"71"},{"text":"3 Is the letter a in the phrase as well as strong /æ/ or weak /ə/?Weak /ə/.","slide":98,"shape":"21","bookPage":"71"},{"text":"Main ideas\nAdditional details\nScientists looked, in particular, at how computers affect our (1) memory.\nThey wanted to find out if computers have changed the way we remember (6) information and knowledge.","slide":113,"shape":"15","bookPage":"71"},{"text":"Main ideas\nAdditional details\nWhat we think when we are asked (2) difficult questions has changed due to (3) websites like Google™.\nIn the past, people tried to think of the (7) answer to the question.Now people think about (8) how to find the answer. e.g. They think about what they might (9) put into Google™.","slide":114,"shape":"16","bookPage":"71"},{"text":"Main ideas\nAdditional details\nThe type of (4) information we remember has changed.\nPeople now forget (10) facts, especially if they know the information will be saved in a computer.They remember the (11) location of the fact.","slide":115,"shape":"16","bookPage":"71"},{"text":"Main ideas\nAdditional details\nComputers are not making us stupid, but they are making us (5) lazy.\nWe are spending time remembering where to (12) find information but not on remembering the information itself.","slide":116,"shape":"15","bookPage":"71"},{"text":"1 I am able to run quite quickly, but I don’t like to run when it is hot.","slide":122,"shape":"16","bookPage":"66"},{"text":"2 Mohammed was able to write on a laptop when he was a child.","slide":122,"shape":"18","bookPage":"66"},{"text":"3 Sunita wasn’t able to play music well until she took lessons.","slide":123,"shape":"16","bookPage":"66"},{"text":"4 My little sister couldn’t see very well when she was young. Then she got glasses.","slide":123,"shape":"18","bookPage":"66"},{"text":"5 Because she studied a lot, Jade was able to pass her science exam.","slide":124,"shape":"10","bookPage":"66"},{"text":"6 Are you able to take good photos with your phone?","slide":124,"shape":"12","bookPage":"66"},{"text":"7 Were you able to use the phone when you were three years old?","slide":124,"shape":"6","bookPage":"66"},{"text":"Possible abilitiesspeak Chinese; play the guitar; swim; cook; ride a bicycle; draw; type; sing; takephotos","slide":127,"shape":"14","bookPage":"67"},{"text":"Possible exchangeA: Can you swim?B: Yes, I can.A: Could you swim when you were five?B: No, I couldn’t.","slide":127,"shape":"16","bookPage":"67"},{"text":"How do I save a file in (1) the cloud instead of on my (2) computer / laptop?","slide":130,"shape":"8","bookPage":"67"},{"text":"laptop","slide":132,"shape":"13","bookPage":"68"},{"text":"turn off / on","slide":132,"shape":"14","bookPage":"68"},{"text":"Wi-Fi","slide":132,"shape":"15","bookPage":"68"},{"text":"the cloud","slide":132,"shape":"5","bookPage":"68"},{"text":"log in","slide":132,"shape":"16","bookPage":"68"},{"text":"password","slide":132,"shape":"17","bookPage":"68"},{"text":"mouse","slide":132,"shape":"18","bookPage":"68"},{"text":"keyboard","slide":132,"shape":"9","bookPage":"68"},{"text":"1 How can people remember their passwords? What is your advice?Possible answer: One option is to use a password manager.","slide":134,"shape":"17","bookPage":"68"},{"text":"2 What do you use the cloud for?Possible answer: I use the cloud to keep a copy of my schoolwork.","slide":134,"shape":"19","bookPage":"68"},{"text":"3 Which do you prefer to use: a laptop or a computer that is on your desk?Possible answer: I prefer a laptop because I can take it to different places.","slide":134,"shape":"6","bookPage":"68"},{"text":"1 Do you prefer using a touchscreen or typing on real keys. Why?Possible answer: I prefer real keys for long pieces of writing.","slide":149,"shape":"17","bookPage":"68"},{"text":"2 What type of apps do you use most: games, social media or another type? Why?Possible answer: I use messaging apps most because they help me stay in touch.","slide":149,"shape":"18","bookPage":"68"},{"text":"3 What do you look for when you surf the internet?Possible answer: I look for information for schoolwork.","slide":149,"shape":"19","bookPage":"68"},{"text":"4 Do you call and talk to people or do you only text them? Why?Possible answer: I text for short messages and call for longer conversations.","slide":149,"shape":"20","bookPage":"68"},{"text":"5 When was the last time your phone’s battery stopped working at a bad time? What happened next?Possible answer: My battery once stopped on the way home, so I asked to use a friend’s phone.","slide":150,"shape":"12","bookPage":"68"},{"text":"6 Do you always carry a charger with you so you can use your phone at any time? Why / Why not?Possible answer: I usually carry a charger on long trips.","slide":150,"shape":"13","bookPage":"68"},{"text":"7 Which type of mobile device do you prefer: a phone or a tablet? Why?Possible answer: I prefer a phone because it fits in my pocket.","slide":150,"shape":"14","bookPage":"68"},{"text":"8 How long do you charge your phone when it has no power?Possible answer: Charging time depends on my phone and charger.","slide":151,"shape":"12","bookPage":"68"},{"text":"My brother cannot find the charger.","slide":155,"shape":"6","bookPage":null},{"text":"She is able to send a text.","slide":155,"shape":"9","bookPage":null},{"text":"My phone has stopped working. Its battery is empty. I need a charger for that battery. My brother is lending me his charger.","slide":156,"shape":"6","bookPage":null},{"text":"The computer helped me with my homework. I found a useful website. The website had a diagram of a robot. That diagram helped me understand its parts.","slide":157,"shape":"6","bookPage":null},{"text":"A student is using a tablet at a library table. She can read information on its screen.","slide":158,"shape":"7","bookPage":null},{"text":"The student is sitting in a quiet library. She could search for information for her homework.","slide":159,"shape":"7","bookPage":null},{"text":"1. In the past, the high cost limited robot use: robots were too expensive.","slide":164,"shape":"5","bookPage":null},{"text":"11. How does the host introduce the idea of human-like robots?\nA. By comparing the price of home and factory robots.\nB. By moving from familiar uses to people-like robots.\nC. By explaining how people build robots at home.","slide":164,"shape":"8","bookPage":null},{"text":"1. The podcast is made by students for students.\nAnswer: TRUE","slide":167,"shape":"5","bookPage":null},{"text":"11. Robotic arms were first used at a hospital in London.\nAnswer: NOT GIVEN","slide":167,"shape":"8","bookPage":null},{"text":"My sister could type quickly when she was ten.","slide":176,"shape":"6","bookPage":null},{"text":"Are you able to log in?","slide":176,"shape":"9","bookPage":null},{"text":"I managed to finish the work after all. At first, I could not remember my password. I found the password in my notebook. With it, I was able to log in.","slide":177,"shape":"6","bookPage":null},{"text":"The small robot surprised our class. It could carry a box across the room. The box contained our books. Those books arrived without falling out.","slide":178,"shape":"6","bookPage":null},{"text":"An older learner is using a computer at home. She is able to move the mouse. She may be learning a new skill.","slide":179,"shape":"7","bookPage":null},{"text":"The computer can show useful information. The learner can look at it carefully. She can practise this new skill every day.","slide":180,"shape":"7","bookPage":null},{"text":"Advantages (+)\nDisadvantages (−)\n2 People remember where and how to find facts.3 Computers aren’t making us stupid.\n1 People forget facts that are stored on computers.4 Computers are making us lazy.5 People aren’t trying to remember information any more.","slide":184,"shape":"14","bookPage":"73"},{"text":"Advantages (+)\nDisadvantages (−)\n2 People remember where and how to find facts.3 Computers aren’t making us stupid.Stored files can help us check information that we have forgotten.\n1 People forget facts that are stored on computers.4 Computers are making us lazy.5 People aren’t trying to remember information any more.We may have difficulty finding information when we cannot access our files.","slide":186,"shape":"14","bookPage":"73"},{"text":"Technology: translation appsAdvantages: help us understand unfamiliar words; support simplecommunication.Disadvantages: translations may contain mistakes; learners may depend on themtoo much.","slide":190,"shape":"14","bookPage":"74"},{"text":"Comparing ideasAdd a partner’s idea only if you understand it and can explain why it matters.","slide":190,"shape":"16","bookPage":"74"},{"text":"Main argument: Technology, such as translation apps, can affect our day-to-day lives.","slide":191,"shape":"6","bookPage":"74"},{"text":"Advantages (+)\nDisadvantages (−)\nHelp us understand unfamiliar words.Support simple communication.\nTranslations may contain mistakes.Learners may depend on them too much.","slide":191,"shape":"14","bookPage":"74"},{"text":"Translation appsFor a short everyday message, quick translation can be useful. For an importantmessage, a serious translation mistake matters more than speed.","slide":194,"shape":"12","bookPage":"74"},{"text":"4  In conclusion, it seems that computers are not making us stupid, but / however they are\nmaking us lazy!","slide":198,"shape":"6","bookPage":"75"},{"text":"3 … it seems that people now forget facts, especially if they know the information will be saved in a file. On the other hand / However, an advantage is they remember the location of the fact: in other words, where to find it.","slide":199,"shape":"16","bookPage":"75"},{"text":"1a Computers help people look for things and they can find information quickly.","slide":203,"shape":"16","bookPage":"76"},{"text":"1b Computers help people look for things, but they can make people lazy.","slide":203,"shape":"17","bookPage":"76"},{"text":"2a Technology is now important for our social lives, but traditional activities like writing letters are disappearing.","slide":203,"shape":"18","bookPage":"76"},{"text":"2b Technology is now important for our social lives and also makes it easier for us to communicate with friends.","slide":203,"shape":"19","bookPage":"76"},{"text":"3a Robots assist people with difficult jobs as well as helping take care of elderly and disabled people.","slide":203,"shape":"6","bookPage":"76"},{"text":"3b Robots assist people with difficult jobs. However, some people think they are bad because people lose their jobs when robots are used.","slide":204,"shape":"17","bookPage":"76"},{"text":"Which introduction is better?1b Today I’m going to present my report on smartwatches. Smartwatches are very useful, but people don’t know how useful they are. The main argument I’m going to present is that more people should use smartwatches because they can help us a lot.","slide":208,"shape":"13","bookPage":"77"},{"text":"Which conclusion is better?2b To conclude, there are many reasons why more people should have smartwatches. The facts in support of this idea are very strong. I hope people will think about this.","slide":208,"shape":"15","bookPage":"77"},{"text":"Translation appsToday I am going to present my report on translation apps. The main argument Iam going to present is that these apps can help us communicate, but we need tocheck important translations.","slide":212,"shape":"12","bookPage":"77"},{"text":"Giving reasonsTranslation apps are useful since they can explain unfamiliar words quickly.Thanks to these apps, people can understand some short messages in anotherlanguage. Important messages need checking because of possible mistakes.","slide":214,"shape":"12","bookPage":"77"},{"text":"Adding and contrasting pointsTranslation apps explain words and help people understand simple messages.They can save time, too. However, they may make mistakes. We can use them for afirst idea, but we should check important messages carefully.","slide":217,"shape":"12","bookPage":"77"},{"text":"Restating the argumentTo conclude, translation apps can support communication, but careful checking isstill important.","slide":219,"shape":"12","bookPage":"78"},{"text":"Possible report: introductionToday I am going to present my report on translation apps. My main argument isthat these apps can help us communicate, but we need to check importanttranslations.","slide":223,"shape":"14","bookPage":"78"},{"text":"Possible report: main pointsTranslation apps are useful since they can explain unfamiliar words quickly. Theyalso help people understand short messages. However, they may make mistakes.Because of this risk, we should check important messages carefully.","slide":223,"shape":"16","bookPage":"78"},{"text":"Possible report: conclusionTo conclude, translation apps can support communication, but careful checking isstill important.","slide":224,"shape":"14","bookPage":"78"},{"text":"Possible partner responseI agree that the apps are useful for simple messages. I also agree that we need tocheck important information because a mistake could change the meaning.","slide":224,"shape":"16","bookPage":"78"},{"text":"This app is useful but it needs the internet.","slide":228,"shape":"6","bookPage":null},{"text":"On the other hand, the screen is quite small.","slide":228,"shape":"9","bookPage":null},{"text":"This device helps me, although it is not perfect. My tablet makes reading easy. Its large screen shows a full page clearly. On the other hand, that large screen makes the tablet harder to carry.","slide":229,"shape":"6","bookPage":null},{"text":"There is more than one reason I use this app. The app helps me practise new words. It also records my pronunciation of those words. I can listen to the recordings and try again.","slide":230,"shape":"6","bookPage":null},{"text":"Shared online notes could help these students collect ideas in one place. They could save their information in one file. However, they would need an internet connection to update it online. Paper notes could be useful if the connection stopped working.","slide":231,"shape":"7","bookPage":null},{"text":"The laptop could help these students share a file with other classmates. They could also use it to find information. However, the paper notebook does not need Wi-Fi. I would use both tools for different parts of the task.","slide":232,"shape":"7","bookPage":null}];
